parameters.prompt:
=You are ZenInbox AI, a calm and emotionally intelligent email triage analyst. Your mission is to de-escalate anxiety, strip panic jargon and passive aggression, and extract clear actionable intent.

Incoming Email:
Subject: {{ $json.subject }}
Sender: {{ $json.from }}
Body:
{{ $json.text || $json.body || $json.html || 'No body content' }}

Return ONLY a single valid JSON object with exactly three keys (no markdown code blocks, no backticks, no preamble):
{
  "intent": "<concise purpose — 15 words max>",
  "summary": "<rewrite in supportive, objective tone — strip panic jargon, false urgency, guilt-tripping, corporate passive-aggression>",
  "draft": "<polite, professional reply establishing healthy boundaries>"
}

parameters.jsCode:
const item = $input.first().json;
const rawText = item.text || item.response || item.content || item.output || (typeof item === 'string' ? item : JSON.stringify(item));

let cleanText = String(rawText).trim()
  .replace(/^```(?:json)?\s*/i, '')
  .replace(/\s*```$/i, '')
  .trim();

let parsed = {};
try {
  parsed = JSON.parse(cleanText);
} catch (err) {
  const match = cleanText.match(/\{[\s\S]*\}/);
  if (match) {
    try {
      parsed = JSON.parse(match[0]);
    } catch (e) {
      parsed = {};
    }
  }
}

const imapData = $('Incoming Email (IMAP)').first()?.json || {};

return [{
  json: {
    message_id: imapData.messageId || imapData.id || `imap-${Date.now()}`,
    sender: imapData.from || imapData.sender || "External Correspondent <sender@partner.org>",
    subject: imapData.subject || "Project Update & Review",
    raw_body: imapData.text || imapData.body || cleanText,
    intent: parsed.intent || "Inquiry review",
    summary: parsed.summary || cleanText.slice(0, 300) || "Sender provided an update.",
    draft: parsed.draft || "Thank you for your email. I have received your message and will review it shortly.",
    received_at: imapData.date || new Date().toISOString()
  }
}];
